using System.Runtime.InteropServices;
using System.Text.Json;
using TextText.Core;
static class FolderCaseRecoveryTests
{
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool MoveFileW(string source,string target);
    sealed class Handler(Func<HttpRequestMessage,Task<HttpResponseMessage>> send):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct)=>send(r);}
    static SyncEngine.State State(TextPackStore store)=>JsonSerializer.Deserialize<SyncEngine.State>(File.ReadAllBytes(Path.Combine(store.StateDirectory,"sync.json")))!;
    sealed record Fixture(TextPackStore Store,Test.Fake Remote,SyncEngine Engine,SyncEngine.FolderSyncCommand Command);
    static async Task<Fixture> Make(string temp,string name){var store=new TextPackStore(Path.Combine(temp,name),Path.Combine(temp,name+"-state"));AccountRootOwnership.Open(store,new Uri("https://texttext.test"),"folder-workspace","folder-account");store.EnsureFolders(["Notes/Empty child"]);var remote=new Test.Fake{SupportsFolderCaseMoves=true,ManifestRevision=new string('a',64),Folders=["Notes","Notes/Empty child"],AuthoritativeFolders=["Notes","Notes/Empty child"]};var engine=Test.NewSync(store,remote);await engine.SyncAsync();if(!MoveFileW(store.Resolve("Notes"),store.Resolve("notes")))throw new IOException("Fixture directory rename failed.");remote.FolderMove=_=>throw new HttpRequestException("Unknown original outcome");try{await engine.SyncAsync();}catch(HttpRequestException){}var command=State(store).FolderCommand!;return new(store,remote,engine,command);}
    static FolderCaseRecoveryReply Review(Fixture f)=>new("review",new string('c',64),f.Command.Request.OperationId,"Notes","notes",new string('d',64),new string('a',64),["Notes","Notes/Empty child"],[]);
    static FolderCaseRecoveryReply Cancelled(Fixture f)=>new("cancelled",new string('c',64),f.Command.Request.OperationId,"Notes","notes",new string('d',64),new string('a',64));
    public static async Task Run(string temp,Action<bool,string> check)
    {
        var operation=Guid.NewGuid().ToString("D");var command=new FolderCaseMoveRequest(operation,"Notes","notes",new string('a',64),["Notes"],[]);var requests=0;
        var wireCheck=typeof(SyncEngine).GetMethod("FolderWireBlockReason",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!;
        string? Block(FolderCaseMoveRequest r)=>(string?)wireCheck.Invoke(null,[r]);
        check(Block(command) is null,"representable automatic folder command fits both move and recovery wire bounds");
        check(Block(command with{Source=new string('a',257)}) is not null&&Block(command with{Folders=[new string('a',257)]}) is not null&&Block(command with{Items=[new("id",new string('a',1025),new string('a',64))]}) is not null,"automatic folder command validates folder and item path bounds before durable intent");
        check(Block(command with{Items=Enumerable.Range(0,20001).Select(i=>new FolderCaseMoveItem("item-"+i,"Notes/"+i+".textpack",new string('a',64))).ToArray()}) is not null,"automatic folder command refuses over20k source items before durable intent");
        check(Block(command with{Items=Enumerable.Range(0,5000).Select(i=>new FolderCaseMoveItem("item-"+i,"Notes/"+new string('a',990)+".textpack",new string('a',64))).ToArray()}) is not null,"automatic folder command reserves recovery wrapper headroom under4MiB serialized body");
        using(var client=new HttpClient(new Handler(async r=>{requests++;using var body=JsonDocument.Parse(await r.Content!.ReadAsStringAsync());var p=body.RootElement;check(r.RequestUri!.AbsolutePath=="/api/vault/items/folder-case-moves/recovery"&&p.GetProperty("command").GetProperty("operationId").GetString()==operation,"HTTP folder recovery binds exact endpoint and immutable original command");var cancel=p.GetProperty("action").GetString()=="cancel";if(cancel)check(p.GetProperty("consent").GetBoolean()&&p.GetProperty("inspection").GetString()==new string('d',64),"HTTP folder cancellation sends explicit consent and fresh server inspection");return new(System.Net.HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(cancel?(object)new{state="cancelled",operationId=operation,requestHash=new string('c',64),source="Notes",destination="notes",inspection=new string('d',64),manifestRevision=new string('a',64)}:new{state="review",operationId=operation,requestHash=new string('c',64),source="Notes",destination="notes",inspection=new string('d',64),manifestRevision=new string('a',64),folders=new[]{"Notes"},items=Array.Empty<object>()}))};}))) {
            var transport=new HttpSyncTransport(client,new("https://texttext.test"),"items",()=>Task.FromResult("fixture"));var read=await transport.RecoverFolderCaseAsync(command,false,null);var cancel=await transport.RecoverFolderCaseAsync(command,true,read.Inspection);check(requests==2&&read.State=="review"&&cancel.State=="cancelled","HTTP folder recovery strict review/cancel union decodes actual wire shape");
        }
        using(var client=new HttpClient(new Handler(_=>Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new StringContent("{\"state\":\"cancelled\",\"requestHash\":\""+new string('c',64)+"\",\"operationId\":\""+operation+"\",\"source\":\"Notes\",\"destination\":\"notes\",\"inspection\":\""+new string('d',64)+"\",\"manifestRevision\":\""+new string('a',64)+"\",\"future\":true}")})))){var refused=false;try{await new HttpSyncTransport(client,new("https://texttext.test"),"items",()=>Task.FromResult("fixture")).RecoverFolderCaseAsync(command,false,null);}catch(InvalidDataException){refused=true;}check(refused,"HTTP future recovery union fields refuse instead of becoming authoritative cancellation");}
        using(var client=new HttpClient(new Handler(_=>Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new StringContent("{} ")})))){var refused=false;try{await new HttpSyncTransport(client,new("https://texttext.test"),"items",()=>Task.FromResult("fixture")).RecoverFolderCaseAsync(command,false,null);}catch(InvalidDataException){refused=true;}check(refused,"HTTP recovery without a state is classified as an invalid server response");}
        if(!OperatingSystem.IsWindows()){Console.WriteLine("SKIP physical folder recovery fixtures require actual Windows.");return;}
        {
            var f=await Make(temp,"offline");var state=File.ReadAllBytes(Path.Combine(f.Store.StateDirectory,"sync.json"));f.Remote.FolderRecovery=(_,_,_,_)=>throw new HttpRequestException("offline");var row=await f.Engine.FolderMoveRecoveryReadAsync();check(row is {State:"unavailable",RequestHash:null,Inspection:null}&&row.ResolutionBlocked is not null&&!row.From.Present&&row.To.Present&&File.ReadAllBytes(Path.Combine(f.Store.StateDirectory,"sync.json")).SequenceEqual(state),"offline folder recovery exposes exact retained command/local proof without inventing verified server state");
            f.Remote.FolderRecovery=(_,_,_,_)=>Task.FromResult(Review(f) with{Items=[null!]});row=await f.Engine.FolderMoveRecoveryReadAsync();check(row!.State=="unavailable"&&row.RequestHash is null&&row.ResolutionBlocked is not null,"malformed authoritative topology remains inspectable as unavailable without a counterfeit cancellation");
            f.Remote.FolderRecovery=(_,_,_,_)=>new TaskCompletionSource<FolderCaseRecoveryReply>(TaskCreationOptions.RunContinuationsAsynchronously).Task;var watch=System.Diagnostics.Stopwatch.StartNew();row=await f.Engine.FolderMoveRecoveryReadAsync();check(row!.State=="unavailable"&&watch.Elapsed<TimeSpan.FromSeconds(4),"folder recovery inspect is bounded while server is unavailable");
        }
        {
            var f=await Make(temp,"held-sync");f.Remote.FolderRecovery=(_,_,_,_)=>Task.FromResult(Review(f));f.Remote.ManifestEntered=new(TaskCreationOptions.RunContinuationsAsynchronously);f.Remote.HoldManifest=new(TaskCreationOptions.RunContinuationsAsynchronously);var active=f.Engine.SyncAsync();await f.Remote.ManifestEntered.Task;var row=await f.Engine.FolderMoveRecoveryReadAsync().WaitAsync(TimeSpan.FromSeconds(2));check(row!.State=="review","folder recovery lists without waiting behind a hung ordinary sync gate");f.Remote.HoldManifest.SetResult();try{await active;}catch(HttpRequestException){}
        }
        {
            var f=await Make(temp,"legacy-unrepresentable");var state=State(f.Store);state.FolderCommand=state.FolderCommand! with{Request=f.Command.Request with{Folders=["Notes","Notes/"+new string('a',251)]}};TextPackStore.AtomicWrite(Path.Combine(f.Store.StateDirectory,"sync.json"),JsonSerializer.SerializeToUtf8Bytes(state));var exact=File.ReadAllBytes(Path.Combine(f.Store.StateDirectory,"sync.json"));var calls=0;f.Remote.FolderRecovery=(_,_,_,_)=>{calls++;throw new Exception("Unrepresentable command must not reach server.");};var row=await f.Engine.FolderMoveRecoveryReadAsync();check(row!.State=="unavailable"&&row.ResolutionBlocked!.Contains("contract")&&calls==0&&File.ReadAllBytes(Path.Combine(f.Store.StateDirectory,"sync.json")).SequenceEqual(exact),"legacy unrepresentable command remains inspectable with clear review error and no authoritative request");var refused=false;try{await f.Engine.SyncAsync();}catch(IOException){refused=true;}check(refused&&File.ReadAllBytes(Path.Combine(f.Store.StateDirectory,"sync.json")).SequenceEqual(exact),"legacy unrepresentable command replay refuses without clearing or rewriting immutable state");
        }
        foreach(var mode in new[]{"stale-local","stale-server","cancel","after-proof","completed"}){
            var f=await Make(temp,mode);var cancelCount=0;var cancelled=false;f.Remote.FolderRecovery=(_,cancel,_,_)=>{if(cancel){cancelCount++;cancelled=true;}return Task.FromResult(cancelled?Cancelled(f):Review(f));};
            FolderCaseMoveReceipt? completed=null;if(mode=="completed"){var r=f.Command.Request;completed=new(r.OperationId,"moved",r.Source,r.Destination,["notes","notes/Empty child"],[],new string('b',64));f.Remote.FolderRecovery=(_,_,_,_)=>Task.FromResult(new FolderCaseRecoveryReply("completed",new string('c',64),Result:completed));f.Remote.FolderMove=_=>{f.Remote.Folders=f.Remote.AuthoritativeFolders=["notes","notes/Empty child"];f.Remote.ManifestRevision=new string('b',64);return Task.FromResult(completed);};}
            var row=await f.Engine.FolderMoveRecoveryReadAsync();check(row!.Command==f.Command.Request||JsonSerializer.Serialize(row.Command)==JsonSerializer.Serialize(f.Command.Request),mode+" recovery row retains exact immutable command");
            if(mode=="stale-local")File.WriteAllText(f.Store.Resolve("notes/new.bin"),"new local bytes after inspection");if(mode=="stale-server")f.Remote.FolderRecovery=(_,_,_,_)=>Task.FromResult(Review(f) with{Inspection=new string('e',64)});
            var callbacks=0;var refused=false;try{await f.Engine.ResolveFolderMoveRecoveryAsync(row.Id,row.Inspection,row.LocalInspection,row.RequestHash!,()=>{if(mode=="after-proof"&&++callbacks==5)throw new OperationCanceledException();});}catch(Exception e)when(e is FileChangedException or OperationCanceledException){refused=true;}
            if(mode is "stale-local"or"stale-server"){check(refused&&cancelCount==0&&State(f.Store).FolderCommand is not null,mode+" refuses stale consent before issuing any cancellation");continue;}
            if(mode=="after-proof"){check(refused&&cancelCount==1&&State(f.Store).FolderCommand is not null&&File.Exists(Path.Combine(f.Store.StateDirectory,"folder-sync-cancellations",row.Id+".json")),"cancellation after durable server-proof export retains command and immutable receipt before acknowledgement");row=await f.Engine.FolderMoveRecoveryReadAsync();await f.Engine.ResolveFolderMoveRecoveryAsync(row!.Id,row.Inspection,row.LocalInspection,row.RequestHash!);}
            check(State(f.Store).FolderCommand is null&&Directory.Exists(f.Store.Resolve("notes/Empty child"))&&f.Remote.UploadCount==0,mode+" verified recovery clears only command state and preserves both current folder paths");
            if(mode!="completed")check(File.Exists(Path.Combine(f.Store.StateDirectory,"folder-sync-cancellations",row.Id+".json")),mode+" cancelled tombstone is retained durably before local command removal");
        }
    }
}
